  "claim": {
    "component_id": "C052",
    "value": "When observability is the main obstacle, an instrumentation canary is a proposed next deployment action.",
    "scope": "A conditional choice using surviving alternatives; observability is not asserted to be the actual main obstacle.",
    "provenance": {
      "refs": [
