          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly supplies the conditional instrumentation-canary choice and its role in choosing the next deployment."
    }
  },
  "signal_basis": {
    "component_id": "C052_SIGNAL",
    "value": "The evidence comparison cannot discriminate among explanations, with missing phase timing or coverage information constituting the main obstacle. The proposed operation is an instrumentation canary collecting that missing information.",
    "scope": "Conditional information gathering when observability limits the comparison; the proposed canary has bounded sampling and logging overhead and collects no document contents.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
